import json
import math
import statistics
import sys
from pathlib import Path

out = Path(sys.argv[1])
dates = ["2024-03-01", "2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08"]
tickers = ["AAA", "BBB"]
closes = {
    "AAA": [200.0, 204.0, 202.0, 198.0, 201.0, 205.0],
    "BBB": [40.0, 40.4, 40.8, 41.2, 41.6, 42.0],
}


def w(name, obj):
    d = out / name
    d.mkdir(parents=True, exist_ok=True)
    (d / "sample.json").write_text(json.dumps(obj, indent=2) + "\n")


rows = [
    {"date": "2024-03-04", "ticker": "BBB", "close": 40.4},
    {"date": "2024-03-01", "ticker": "AAA", "close": 200.0},
    {"date": "2024-03-01", "ticker": "BBB", "close": 40.0},
    {"date": "2024-03-04", "ticker": "AAA", "close": 204.0},
    {"date": "2024-03-05", "ticker": "AAA", "close": 202.0},
    {"date": "2024-03-05", "ticker": "BBB", "close": None},
    {"date": "2024-03-06", "ticker": "AAA", "close": 198.0},
    {"date": "2024-03-06", "ticker": "BBB", "close": 41.2},
]
w("mdata.RawRow", rows)
prices = {"dates": dates, "tickers": tickers, "closes": closes}
w("mdata.Prices", prices)

rets = {t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}
w("risk.Returns", returns)

window = 2
vol = {}
for t, r in rets.items():
    vol[t] = [
        None if i < window else statistics.stdev(r[i - window : i]) * math.sqrt(252)
        for i in range(len(r))
    ]
volseries = {"returns": returns, "window": window, "annualized": True, "values": vol}
w("risk.VolSeries", volseries)


def summary(t):
    r = rets[t]
    ar = 252 * statistics.mean(r)
    av = math.sqrt(252) * statistics.stdev(r)
    return {"ticker": t, "ann_return": ar, "ann_vol": av, "sharpe": ar / av if av else 0.0,
            "last_vol": vol[t][-1]}


w("risk.TickerSummary", summary("AAA"))


def dd(t):
    wealth, peak, pk_i = 1.0, 1.0, 0
    best = (0.0, 0, 0)
    for i, r in enumerate(rets[t], start=1):
        wealth *= math.exp(r)
        if wealth > peak:
            peak, pk_i = wealth, i
        depth = wealth / peak - 1
        if depth < best[0]:
            best = (depth, pk_i, i)
    return {"ticker": t, "depth": best[0], "peak_date": dates[best[1]], "trough_date": dates[best[2]]}


dds = [dd("AAA"), dd("BBB")]
w("risk.Drawdown", dds)
rows_out = []
for t, d in zip(tickers, dds):
    s = summary(t)
    rows_out.append({**s, "max_drawdown": d["depth"], "peak_date": d["peak_date"],
                     "trough_date": d["trough_date"]})
w("risk.Report", {"path": "reports/risk.json", "rows": rows_out})
print(json.dumps(dds), json.dumps(vol))
